}

public function testConcurrentRatingAndCorrectionsDoNotDoubleCharge(): void
{
    $this->fixtures();
    $first = self::startCli('app:billing:rate');
    $second = self::startCli('app:billing:rate');
    $results = [self::finishCli($first), self::finishCli($second)];
    sort($results);
